package android.view;public class MotionEvent {public static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_MOVE=2,ACTION_CANCEL=3,ACTION_POINTER_DOWN=5,ACTION_POINTER_UP=6,ACTION_HOVER_MOVE=7,ACTION_POINTER_INDEX_SHIFT=8,TOOL_TYPE_UNKNOWN=0;public int action,source;public long time;public int[] ids;public float[] xs,ys;public static class PointerCoords{public float x,y,pressure,size;public void clear(){x=y=pressure=size=0;}}public static class PointerProperties{public int id,toolType;}public static MotionEvent obtain(long down,long time,int action,int count,PointerProperties[] pp,PointerCoords[] pc,int ms,int bs,float xp,float yp,int device,int edge,int source,int flags){MotionEvent e=new MotionEvent();e.action=action;e.time=time;e.source=source;e.ids=new int[count];e.xs=new float[count];e.ys=new float[count];for(int i=0;i<count;i++){e.ids[i]=pp[i].id;e.xs[i]=pc[i].x;e.ys[i]=pc[i].y;}return e;}public int getActionMasked(){return action&255;}public int getSource(){return source;}public boolean isFromSource(int s){return (source&s)==s;}public long getEventTime(){return time;}public void setDisplayId(int d){}}
